"""Canonical release prompts copied byte-for-byte from FoG/prompts/vision.py."""

vision_cot_prompt = '\nYou will receive a multi-hop question along with a list of topic entities from a Freebase knowledge graph. Your task is to predict the chain of relations connecting the topic entities to the answer.\n\nCRITICAL: Predict relations using Freebase\'s `domain.type.property` naming convention, e.g.:\n- people.person.nationality (NOT person.nationality)\n- film.actor.film (NOT actor.movies)\n- sports.sports_team.championships (NOT team.won_championship)\n\nKey rules:\n1. Many paths go through CVT (Compound Value Type) intermediate nodes — predict ALL hops explicitly. For example, "who acted in X" needs TWO relations: film.actor.film -> film.performance.film (through a Performance CVT node).\n2. When a question asks about dates/times, include temporal relations like time.event.start_date or time.event.end_date.\n3. When a question asks "what type of X" or filters by entity type, include common.topic.notable_types.\n4. Use "->" for outgoing relations and "<-" for incoming relations.\n5. Try to include ALL provided topic entities in the chain.\n6. Output exactly ONE predicted relation chain. Do not provide alternatives,\n   multiple candidates, or additional Thinking CoT lines.\n\nFormat:\nThinking CoT: "topic_entity" -> domain.type.property -> ? -> domain.type.property -> answer_type\nAnswer Type: <type>\n\nExamples:\n\nQ: What country bordering France contains an airport that serves Nijmegen?\nTopic Entities: {{m.05g2b: Nijmegen, m.0f8l9c: France}}\nA:\nThinking CoT: "Nijmegen" <- aviation.airport_served.airport <- airport -> location.location.containedby -> country -> location.location.adjoin_s -> location.adjoining_relationship.adjoins -> "France"\nAnswer Type: country\n\nQ: Where did the "Country Nation World Tour" concert artist go to college?\nTopic Entities: {{m.010qhfmm: Country Nation World Tour}}\nA:\nThinking CoT: "Country Nation World Tour" <- music.artist.concert_tours <- artist -> people.person.education -> education.education.institution\nAnswer Type: educational institution\n\nQ: What year did the team with mascot Lou Seal last win the World Series?\nTopic Entities: {{m.0cv9fc: Lou Seal}}\nA:\nThinking CoT: "Lou Seal" <- sports.sports_team.team_mascot <- team -> sports.sports_team.championships -> time.event.start_date\nAnswer Type: date\n\nQ: What type of government does the country where Neymar is from have?\nTopic Entities: {{m.03zv9: Neymar}}\nA:\nThinking CoT: "Neymar" -> people.person.nationality -> country -> government.governmental_jurisdiction.governing_officials -> government.government_position_held.basic_title -> common.topic.notable_types\nAnswer Type: government type\n\nThe question is:\nQ: {question}\nTopic Entities: {topic_entities}\nA:\n'

vision_path_select_complementary_set_prompt = '\nYou are analyzing a knowledge graph visualization to find reasoning paths that can answer a question.\n\n**Graph Legend:**\n- Gold/Yellow boxes: Topic entities (starting points, labeled with names)\n- Blue circles with numbers: Intermediate entity sets (Node 1, Node 2, etc.)\n- Arrows: Relations connecting entities; preserve every arrow direction\n\n**Your Task:**\nSelect up to 3 paths as ONE complementary set.\n1. Path 1 should be the strongest complete reasoning chain from a topic entity toward the requested answer type.\n2. Path 2 and Path 3 must add useful coverage: cover a question constraint not covered by earlier paths, use a different relevant relation chain, or reach a different plausible answer branch.\n3. Every Path line must be a complete, independently executable chain. It must contain at least one named Gold/Yellow topic box or Green exploration-center box. Never start a path at "Node X". If two paths share a prefix, repeat that prefix in full on both lines; never split one chain across several Path lines.\n4. For a compositional question, silently identify its atomic constraints first. Prefer a single connected path that covers multiple constraints. Across the selected set, cover as many remaining constraints as are visibly supported by the graph.\n5. Do not output duplicate paths, reordered versions of the same path, or paths that differ only in their terminal node number.\n6. Return 3 paths whenever 3 relevant executable topic-anchored paths exist. Otherwise return every valid relevant path available; if the graph contains any relevant edge from a named anchor, return at least 1 path.\n\n**Output Format:**\nPath 1: TopicEntity1 -> full.relation.name -> Node X\nPath 2: TopicEntity2 <- full.relation.name <- Node Y -> full.relation.name -> Node Z\nPath 3: ...\n\n**Important:**\n- Always use FULL relation names exactly as shown in the Graph Text Description.\n- Preserve arrow direction exactly: use -> for forward edges and <- for backward edges.\n- Treat the Graph Text Description as authoritative for exact connectivity: before output, verify every consecutive `A -> relation -> B` edge verbatim against it.\n- The image supplies topology, not hidden entity names. Use named boxes exactly as displayed, and keep every blue intermediate circle as `Node X`; never replace it with a guessed entity name.\n- Every path must actually exist in both the image and Graph Text Description. Do not use world knowledge to invent a bridge.\n- End toward the entity type requested by the question, not merely at a constraint value or a supporting topic.\n- Output only Path lines, without explanations.\n\n**Question:** {question}\n\n**Graph Text Description:**\n{text_description}\n\n**Thinking CoT (predicted relation chain):**\n{thinking_cot}\n\nSelect the single complementary set of up to three paths:\n'

vision_path_select_retry_prompt = '\nYou are analyzing a knowledge graph visualization to find reasoning paths that can answer a question.\n\n**IMPORTANT: Previous attempts failed!**\nThe following paths were predicted before but could NOT be verified in the knowledge graph (they don\'t exist or have incorrect relation names):\n{failed_paths}\n\nPlease carefully re-examine the graph and select DIFFERENT paths. Make sure to:\n1. Double-check that the relation names EXACTLY match what is shown in the graph\n2. Verify the path connections actually exist in the Graph Text Description\n3. Do NOT repeat any of the failed paths listed above\n4. Make every Path line a complete, self-contained chain containing a named topic or exploration-center box; never start at Node X and never split one chain across multiple Path lines\n5. Keep blue intermediate circles as Node X instead of guessing their entity names\n\n**Graph Legend:**\n- Gold/Yellow boxes: Topic entities (starting points, labeled with names)\n- Blue circles with numbers: Intermediate entity sets (Node 1, Node 2, etc.)\n- Arrows: Relations connecting entities\n  - Arrow pointing TO a node means the relation goes IN that direction\n  - Arrow pointing FROM a node means the relation goes OUT from that direction\n\n**Your Task:**\nGiven the question and the graph image, identify the TOP 3 most promising paths that could lead to the answer.\n\n**Output Format:**\nFor each path, write in this format:\nPath 1: TopicEntity1 -> relation1 -> Node X <- relation2 <- TopicEntity2 <- ...\nPath 2: TopicEntity3 -> relation3 -> Node Y -> relation4 -> Node Z -> ...\nPath 3: ...\n\nWhere:\n- TopicEntity is the name shown in the gold box\n- Node X, Node Y are the numbers shown in blue circles\n- Relations are the labels on the edges\n\n**Important:** \n- Always use the FULL relation names (e.g., "music.artist.genre" not just "genre"). Do not abbreviate or shorten relation names.\n- Pay attention to the DIRECTION of arrows. Use "->" for edges pointing forward (outgoing) and "<-" for edges pointing backward (incoming).\n- Do NOT output paths that do not exist in the graph. If you are unsure from the image, verify by checking the **Graph Text Description** below.\n\n**Question:** {question}\n\n**Graph Text Description:**\n{text_description}\n\n**Thinking CoT (predicted relation chain):**\n{thinking_cot}\n\nBased on the graph image and avoiding the failed paths, please identify the top 3 paths:\n'

vision_path_select_text_only_prompt = '\nYou are analyzing a knowledge graph to find reasoning paths that can answer a question.\n\n**Graph Structure:**\nThe graph contains:\n- Topic entities (starting points): {topic_entities}\n- Intermediate nodes (entity sets): numbered as Node 1, Node 2, etc.\n- Relations connecting these nodes\n\n**Edge List:**\n{text_description}\n\n**Your Task:**\nGiven the question, identify the TOP 3 most promising paths that could lead to the answer.\n\n**Output Format:**\nPath 1: TopicEntity -> relation1 -> Node X -> relation2 -> Node Y -> ...\nPath 2: ...\nPath 3: ...\n\nOutput each complete path on exactly one line. Do not use Markdown, bullets,\ncode fences, explanations, or blank lines between a Path label and its path.\n\n**Question:** {question}\n\n**Thinking CoT (predicted relation chain):**\n{thinking_cot}\n\nPlease identify the top 3 paths:\n'

text_path_select_retry_prompt = '\nYou are analyzing a knowledge graph to find reasoning paths that can answer a question.\n\n**IMPORTANT: Previous attempts failed!**\nThe following paths were predicted before but could NOT be verified in the knowledge graph (they don\'t exist or have incorrect relation names):\n{failed_paths}\n\nPlease carefully re-examine the graph and select DIFFERENT paths. Make sure to:\n1. Double-check that the relation names EXACTLY match what is shown in the Edge List\n2. Verify the path connections actually exist in the Edge List\n3. Do NOT repeat any of the failed paths listed above\n\n**Graph Structure:**\nThe graph contains:\n- Topic entities (starting points): {topic_entities}\n- Intermediate nodes (entity sets): numbered as Node 1, Node 2, etc.\n- Relations connecting these nodes\n\n**Edge List:**\n{text_description}\n\n**Your Task:**\nGiven the question, identify the TOP 3 most promising paths that could lead to the answer.\n\n**Output Format:**\nPath 1: TopicEntity -> relation1 -> Node X -> relation2 -> Node Y -> ...\nPath 2: ...\nPath 3: ...\n\nOutput each complete path on exactly one line. Do not use Markdown, bullets,\ncode fences, explanations, or blank lines between a Path label and its path.\n\n**Important:**\n- Always use the FULL relation names (e.g., "music.artist.genre" not just "genre"). Do not abbreviate or shorten relation names.\n- Pay attention to the DIRECTION of arrows. Use "->" for edges pointing forward (outgoing) and "<-" for edges pointing backward (incoming).\n- Do NOT output paths that do not exist in the Edge List.\n\n**Question:** {question}\n\n**Thinking CoT (predicted relation chain):**\n{thinking_cot}\n\nBased on the Edge List and avoiding the failed paths, please identify the top 3 paths:\n'

vision_single_path_correction_prompt = '\nThe following path could NOT be verified in the knowledge graph. The path structure is correct, but some **relation names** or **arrow directions** may be wrong.\n\n**Failed Path:**\n{failed_path}\n\n**Graph Text Description:**\n{text_description}\n\n**Your Task:**\nKeep the path unchanged — only fix the **relation names** and **arrow directions** based on the Graph Text Description.\n\nRules:\n1. **Do NOT change the path** — keep the same sequence of nodes.\n2. **Relation names** must EXACTLY match those in the Graph Text Description.\n3. **Arrow directions**:\n   - "->" means the relation goes FROM the left node TO the right node (i.e., "A -> relation -> B" in the Graph Text Description)\n   - "<-" means the relation goes FROM the right node TO the left node (i.e., "B -> relation -> A" in the Graph Text Description)\n4. If no valid correction can be found, output "INVALID".\n\nOnly output the corrected path, nothing else.\n\n**Corrected Path:**\n'

vision_summary_cot_prompt = "\nGiven a question, main topic entities, and retrieved knowledge paths, your task is to summarize the paths into a chain of thought (CoT) that connects topic entities to potential answers.\n\nYou must:\n1. Use ONLY entities with IDs from the given paths\n2. Do NOT skip steps - each hop must be explicitly shown\n3. Simplify relation names for readability while keeping the meaning clear\n\n**Question:** {question}\n\n**Main Topic Entities:** {topic_entities}\n\n**Retrieved Paths:**\n{paths}\n\n**Output Format:**\nCoT1: {{entity_id: name}} - {{ <- relation <- }} - {{entity_id: name}} - {{ -> relation -> }} - {{entity_id: name}}\nreason: [Brief explanation of how this chain answers the question]\n\nIf multiple CoT chains are needed:\nCoT2: ...\nreason: ...\n\nExample:\n\nQ: \nQuestion: What country bordering France contains an airport that serves Nijmegen?\nMain Topic Entities: {{m.05g2b: Nijmegen, m.0f8l9c: France}}\nRelated_path: \npath 1 :  {{m.05g2b: Nijmegen}} - {{ -> location.location.nearby_airports  ->,  <- aviation.airport.serves  <- }} - {{m.06cm5d: Weeze Airport}} - {{ -> location.location.containedby  ->,  <- location.location.contains  <- }} - {{m.0345h: Germany}}\npath 2 :  {{m.012x_5p_: Germany}} - {{ -> music.release.region  -> }} - {{m.02j71: Earth}} - {{ <- music.release.region  <- }} - {{m.0sprr4w: So Serene, m.0g801ww: A State of Trance 2009, m.0126m_r6: Alexandria, m.03xsqd1: Bad Dreams / Omissions, m.049ljb7: Myam James, Part 1}} - {{ -> music.release.region  -> }} - {{m.059j2: Netherlands}} - {{ -> location.country.second_level_divisions  ->,  -> location.location.contains  ->,  <- location.administrative_division.second_level_division_of  <-,  <- location.location.containedby  <- }} - {{m.05g2b: Nijmegen}}\npath 3 :  {{m.012x_5p_: Germany}} - {{ -> music.release.region  -> }} - {{m.02j71: Earth}} - {{ -> base.aareas.schema.administrative_area.administrative_children  ->,  -> base.locations.planets.countries_within  ->,  <- base.aareas.schema.administrative_area.administrative_parent  <-,  <- base.locations.countries.planet  <- }} - {{m.0f8l9c: France}} - {{ -> location.location.partially_contains  ->,  <- geography.river.basin_countries  <-,  <- location.location.partially_containedby  <- }} - {{m.06fz_: Rhine}} - {{ -> geography.river.cities  -> }} - {{m.05g2b: Nijmegen}}\n\nA:\nCoT1: {{m.05g2b: Nijmegen}} - {{ <- airport serves to <- }} - {{m.06cm5d: Weeze Airport}} - {{ -> containedby -> }} - {{m.0345h: Germany}} - {{ -> location borders -> }} - {{m.0f8l9c: France}}\nreason: {{m.05g2b: Nijmegen}} - {{ <- aviation.airport.serves <- }} - {{m.06cm5d: Weeze Airport}} found in path 1, {{m.06cm5d: Weeze Airport}} - {{ -> location.location.containedby -> }} - {{m.0345h: Germany}} found in path 1, {{m.0345h: Germany}} - {{ -> location.location.borders -> }} - {{m.0f8l9c: France}} found in path 3, which can be summarized as Nijmegen's airport, Weeze Airport, is contained by Germany, which borders France.\n\nNow summarize the paths for:\n"

vision_explore_prompt = '\nGiven a question, the current retrieved knowledge graph paths, and a summary of what has been found, your task is to identify which nodes or entities should be explored further to find the answer.\n\n**Question:** {question}\n\n**Current Retrieved Paths:**\n{current_paths}\n\n**Summarized Paths:**\n{summarized_paths}\n\n**Summary of Findings:**\n{summary}\n\nBased on the above information, please select the nodes that are most likely to lead to the answer when explored further. These should be nodes that:\n1. Appear in promising paths but need more connections explored\n2. Are intermediate nodes that might connect to the answer\n3. Are related to the predicted answer type\n\nPlease respond in the following format:\nExploration Required: {{node1, node2, node3}}\nReason: [Brief explanation of why these nodes should be explored]\n'

answer_with_vision_paths_prompt = '\nGiven a main question, the predicted thinking chain, the retrieved knowledge graph paths, and the summarized CoT chain, determine if the paths are sufficient to answer the question.\n\n**Question:** {question}\n\n**Thinking CoT:** {thinking_cot}\n\n**Retrieved Paths:**\n{paths}\n\n**Summarized CoT:**\n{summarized_cot}\n\nYour task:\n1. If the paths are sufficient to answer the question, respond with {{Yes}} and provide only the entity name or names copied exactly from the retrieved paths.\n2. If not sufficient, respond with {{No}} and explain what information is missing.\n3. Never write the answer as a sentence. Ignore CVT nodes named Unnamed Entity and supporting/topic entities that are not the requested answer.\n4. Separate multiple answer entity names with ` | `; preserve commas that are part of a single entity name.\n\nFormat:\nresponse: {{Yes}} or {{No}}\nanswer: {{exact entity name | another exact entity name}} (if Yes)\nreason: [explanation]\n'

__all__ = ['vision_cot_prompt', 'vision_path_select_complementary_set_prompt', 'vision_path_select_retry_prompt', 'vision_path_select_text_only_prompt', 'text_path_select_retry_prompt', 'vision_single_path_correction_prompt', 'vision_summary_cot_prompt', 'vision_explore_prompt', 'answer_with_vision_paths_prompt']
